input.command:
$cands = @(
  "C:\Users\olive_\Documents\codigo",
  "C:\Users\olive_\Documentos\codigo",
  "C:\Users\olive_\Documents\Codigo",
  "C:\Users\olive_\OneDrive\Documentos\codigo",
  "C:\Users\olive_\OneDrive\Documents\codigo"
)
foreach ($c in $cands) { if (Test-Path $c) { "ACHEI: $c" } }
"--- Pastas dentro de Documents/Documentos ---"
foreach ($d in @("C:\Users\olive_\Documents","C:\Users\olive_\Documentos","C:\Users\olive_\OneDrive\Documentos","C:\Users\olive_\OneDrive\Documents")) {
  if (Test-Path $d) {
    "[$d]"
    Get-ChildItem -Path $d -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'cod' } | Select-Object -ExpandProperty FullName
  }
}

$path = "C:\Users\olive_\OneDrive\Documentos\codigo"
if (Get-SmbShare -Name "codigo" -ErrorAction SilentlyContinue) {
  "Share 'codigo' ja existe — atualizando acesso."
} else {
  New-SmbShare -Name "codigo" -Path $path -FullAccess "$env:COMPUTERNAME\$env:USERNAME" | Out-Null
  "Share 'codigo' criada."
}
"--- Confirmacao ---"
Get-SmbShare -Name "codigo" | Select-Object Name, Path | Format-List
Get-SmbShareAccess -Name "codigo" | Select-Object AccountName, AccessRight, AccessControlType | Format-Table -AutoSize
